124	// `run --mode cycle` presentation: spawn the engine, hiding its startup banner
125	// and verbose [info] log (VsimFilter), relaying only the program's own output
126	// and any real diagnostics, then restate the lifted cycle count as andesim's own
127	// one-line result under the [andesim] prefix. The count is printed AFTER the run
128	// (the engine logs it at exit), so it follows the program output. Returns the
129	// engine exit code. Unlike fast's exec_passthrough, the parent stays alive to
130	// filter -- fine, because cycle (without --gdb) is a batch run, not interactive.
131	int run_cycle_clean(const std::vector<std::string>& argv) {
132	  VsimFilter filter;
133	  const int rc = run_line_filtered(
134	      argv, [&filter](int stream, std::string_view line) {
135	        std::FILE* dst = nullptr;
136	        switch (filter.classify(stream, line)) {
137	          case VsimFilter::Dest::kStdout: dst = stdout; break;
138	          case VsimFilter::Dest::kStderr: dst = stderr; break;
139	          case VsimFilter::Dest::kDrop: return;
140	        }
141	        std::fwrite(line.data(), 1, line.size(), dst);
142	        std::fputc('\n', dst);
143	      });
144	  if (const std::optional<uint64_t> c = filter.cycles())
145	    std::printf("[andesim] %llu cycles\n", static_cast<unsigned long long>(*c));
146	  return rc;
147	}
