258	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
259	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
260	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
261	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
262	  const char* iceman = std::getenv("ICEMAN");
263	  if (!iceman || !*iceman) {
264	    std::fprintf(stderr,
265	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
266	                 "(export ICEMAN=<path to ICEman binary>)\n");
267	    return 2;
268	  }
269	  // Build vsim argv from the standalone template, appending user passthrough
270	  // and the JTAG port flag.
271	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
272	  if (elf.empty()) return 2;
273	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
274	  std::vector<std::string> vsim_pass = cli.passthrough;
275	  vsim_pass.push_back("--jtag-port");
276	  vsim_pass.push_back(jtag_port);
277	  std::string err;
278	  const std::vector<std::string> vsim_argv =
279	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
280	  if (!err.empty()) {
281	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
282	    return 2;
283	  }
284	  std::fprintf(stderr,
285	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
286	               jtag_port.c_str());
287	  if (fork_background(vsim_argv) < 0) {
288	    std::fprintf(stderr,
289	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
290	    return 1;
291	  }
292	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
293	  // Wait for the port to be LISTENing before launching the debugger (it does not
294	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
295	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
296	  // but launch anyway if it never appears.
297	  if (const int pnum = std::atoi(jtag_port.c_str());
298	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
299	    std::fprintf(stderr,
300	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
301	                 "after 20s; launching the debugger anyway\n",
302	                 jtag_port.c_str());
303	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
304	  // localhost, port 9104) instead of its default real-hardware adapter; without
305	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
306	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
307	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
308	}
