// `andesim run --mode fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
//
// The top selection axis. This minimal slice lands `--mode fast`: resolve the
// built-in qemu engine and hand off to transparent passthrough -- the ELF plus
// everything after `--` becomes QEMU's own command line, run with inherited
// stdio, no timeout, and the exit code propagated, so a gdbstub / monitor /
// semihosting console all behave as if QEMU were invoked directly. `cycle` (F8)
// and `hybrid` (F9) land in later features; their dispatch arms stub for now.
#include <cstdio>
#include <string>
#include <vector>

#include "cli.hpp"
#include "engine_registry.hpp"
#include "models.hpp"
#include "process.hpp"
#include "run_passthrough.hpp"

namespace andes_sim {
namespace {

// `run --mode fast`: QEMU alone, functional, transparent passthrough. Resolves
// the built-in qemu descriptor directly (no engine discovery -- fast needs only
// qemu, and discover_engines would spawn a --describe per Verilator build).
int run_fast(const Cli& cli) {
  if (cli.positional.empty()) {
    std::fprintf(stderr,
                 "andesim run --mode fast: missing ELF (the workload to run; "
                 "e.g. a tests/fixtures/<name>.elf)\n");
    return 2;
  }
  if (cli.positional.size() > 1) {
    std::fprintf(stderr,
                 "andesim run --mode fast: unexpected argument '%s' "
                 "(engine args go after --)\n",
                 cli.positional[1].c_str());
    return 2;
  }
  // fast is QEMU-only; an explicit engine must name it.
  if (!cli.engine.empty() && cli.engine != "qemu") {
    std::fprintf(stderr,
                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
                 cli.engine.c_str());
    return 2;
  }

  // The ELF path is handed to QEMU as-is; this minimal slice does no
  // file-existence or arch validation (that lands with strict validation).
  const EngineDescriptor qemu = builtin_qemu();
  std::string err;
  const std::vector<std::string> argv = passthrough_argv(
      qemu, "standalone", cli.positional[0], cli.passthrough, err);
  if (!err.empty()) {
    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
    return 2;
  }
  return exec_passthrough(argv);
}

}  // namespace

int cmd_run(const Cli& cli) {
  if (cli.model.empty()) {
    std::fprintf(stderr,
                 "andesim run: --mode fast|cycle|hybrid is required "
                 "(pick the composition; see 'andesim run --help')\n");
    return 2;
  }
  if (!find_model(cli.model)) {
    std::fprintf(stderr,
                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
                 cli.model.c_str());
    return 2;
  }
  if (cli.model == "fast") return run_fast(cli);

  std::fprintf(stderr, "andesim run --mode %s: not yet implemented\n",
               cli.model.c_str());
  return 3;
}

}  // namespace andes_sim

// Unit tests for the F7 transparent-passthrough argv assembly (run --mode
// fast). passthrough_argv fills an engine's role invoke template ({bin}/{elf})
// then appends the verbatim post-`--` engine args -- the data path behind
// `run --mode fast prog.elf -- -gdb tcp::1234 -S` behaving like raw QEMU.
//
// The live spawn path (fast's exec_passthrough) is exercised end-to-end by
// tests/andes_sim/test_andes_sim_f7.sh, so this file stays pure (no spawn).
// Plain assert-and-count harness.
#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "run_passthrough.hpp"
#include "test_check.hpp"

using namespace andes_sim;
using andes_sim::test::check_eq;

namespace {

// The standalone template the built-in qemu descriptor ships (engine_registry):
// the andes functional config, {bin}/{elf} to be filled.
EngineDescriptor fake_qemu() {
  EngineDescriptor d;
  d.id = "qemu";
  d.bin_path = "/q";
  d.invoke.push_back(
      {"standalone",
       {"{bin}", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
        "-nographic", "-semihosting-config", "enable=on,target=native", "-bios",
        "{elf}"}});
  return d;
}

}  // namespace

int main() {
  const EngineDescriptor q = fake_qemu();

  // The F7 done-when shape: post-`--` engine args (here a gdbstub) append
  // verbatim AFTER the filled standalone template.
  {
    std::string err;
    std::vector<std::string> got = passthrough_argv(
        q, "standalone", "/prog.elf", {"-gdb", "tcp::1234", "-S"}, err);
    CHECK(err.empty());
    check_eq(got,
             {"/q", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
              "-nographic", "-semihosting-config", "enable=on,target=native",
              "-bios", "/prog.elf", "-gdb", "tcp::1234", "-S"},
             "gdbstub");
  }

  // No passthrough args: just the filled template, {elf} in place.
  {
    std::string err;
    std::vector<std::string> got =
        passthrough_argv(q, "standalone", "/prog.elf", {}, err);
    CHECK(err.empty());
    check_eq(got,
             {"/q", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
              "-nographic", "-semihosting-config", "enable=on,target=native",
              "-bios", "/prog.elf"},
             "no-pass");
  }

  // A role the engine has no template for is an error, not a silent partial
  // argv (the caller must not spawn a half-built command line).
  {
    std::string err;
    std::vector<std::string> got =
        passthrough_argv(q, "accurate-leg", "/prog.elf", {}, err);
    CHECK(got.empty());
    CHECK(!err.empty());
  }

  return andes_sim::test::report("run");
}

